-- Apollo Build Week 4 executable reduced-fatigue protocols.
-- Authoritative content: tool/programmes/apollo_build_12_week_implementation_source.md, Section F.
-- This intentionally creates session definitions only: no programme version or Plan Package.

-- Deterministic, dogfood-only session lineages and revision ids. Collisions fail closed.
DO $$
DECLARE v_existing integer; v_exact integer;
BEGIN
  SELECT count(*) INTO v_existing FROM public.performance_protocols WHERE protocol_id LIKE 'APOLLO-W4-%-R1';
  SELECT count(*) INTO v_exact FROM public.performance_protocols
   WHERE (protocol_id,name,authoring_scope,organisation_id,lifecycle_status) IN (
    ('APOLLO-W4-MON-R1','Apollo Strength','organisation','apollo-dogfood','draft'),
    ('APOLLO-W4-TUE-R1','Apollo Base','organisation','apollo-dogfood','draft'),
    ('APOLLO-W4-WED-R1','Racehorse Strength','organisation','apollo-dogfood','draft'),
    ('APOLLO-W4-THU-R1','Apollo Engine','organisation','apollo-dogfood','draft'),
    ('APOLLO-W4-FRI-R1','Apollo Sculpt','organisation','apollo-dogfood','draft'),
    ('APOLLO-W4-SAT-R1','Apollo Athletic','organisation','apollo-dogfood','draft'),
    ('APOLLO-W4-SUN-R1','Apollo Long','organisation','apollo-dogfood','draft')
   );
  IF v_existing = 7 AND v_exact = 7 THEN RETURN; END IF;
  IF v_existing <> 0 THEN RAISE EXCEPTION 'Apollo Week 4 protocol identity/content conflict'; END IF;
  INSERT INTO public.session_lineages(id,display_name) VALUES
   ('a1400001-0000-4000-8000-000000000001','Apollo Strength'),('a1400002-0000-4000-8000-000000000002','Apollo Base'),
   ('a1400003-0000-4000-8000-000000000003','Racehorse Strength'),('a1400004-0000-4000-8000-000000000004','Apollo Engine'),
   ('a1400005-0000-4000-8000-000000000005','Apollo Sculpt'),('a1400006-0000-4000-8000-000000000006','Apollo Athletic'),
   ('a1400007-0000-4000-8000-000000000007','Apollo Long');
  INSERT INTO public.performance_protocols(protocol_id,name,purpose,published,content_kind,authoring_scope,endorsement_status,organisation_id,session_lineage_id,revision_number,lifecycle_status,duration_min,primary_session_intent,coaching_notes) VALUES
   ('APOLLO-W4-MON-R1','Apollo Strength','Reduced-fatigue Apollo-priority upper-body strength.','false','session','organisation','organisation_approved','apollo-dogfood','a1400001-0000-4000-8000-000000000001',1,'draft',75,'upper_body_strength','All resistance work is approximately 3 RIR.'),
   ('APOLLO-W4-TUE-R1','Apollo Base','Reduced aerobic base, trunk strength and mobility.','false','session','organisation','organisation_approved','apollo-dogfood','a1400002-0000-4000-8000-000000000002',1,'draft',65,'aerobic_base','Track distance, average pace and average HR.'),
   ('APOLLO-W4-WED-R1','Racehorse Strength','Reduced-fatigue lower-body strength and posterior-chain emphasis.','false','session','organisation','organisation_approved','apollo-dogfood','a1400003-0000-4000-8000-000000000003',1,'draft',75,'lower_body_strength','All resistance work is approximately 3 RIR; RDL retains controlled three-second eccentric.'),
   ('APOLLO-W4-THU-R1','Apollo Engine','Controlled 10K-effort intervals.','false','session','organisation','organisation_approved','apollo-dogfood','a1400004-0000-4000-8000-000000000004',1,'draft',46,'intervals','Not a VO2 workout; record every interval pace.'),
   ('APOLLO-W4-FRI-R1','Apollo Sculpt','Reduced-fatigue upper-body hypertrophy.','false','session','organisation','organisation_approved','apollo-dogfood','a1400005-0000-4000-8000-000000000005',1,'draft',75,'upper_body_hypertrophy','All resistance work is approximately 3 RIR; isolation and neck rest are explicit.'),
   ('APOLLO-W4-SAT-R1','Apollo Athletic','Reduced-fatigue power and athletic strength.','false','session','organisation','organisation_approved','apollo-dogfood','a1400006-0000-4000-8000-000000000006',1,'draft',55,'athletic_power','All resistance work is approximately 3 RIR; no conditioning.'),
   ('APOLLO-W4-SUN-R1','Apollo Long','Reduced aerobic endurance and recovery-compatible cardiovascular development.','false','session','organisation','organisation_approved','apollo-dogfood','a1400007-0000-4000-8000-000000000007',1,'draft',70,'aerobic_endurance','No fast finish.');
END $$;

