WHERE NOT EXISTS (SELECT 1 FROM public.session_block_exercises e WHERE e.block_id=v.block_id);

-- A partial block/exercise seed is a corruption, never an invitation to silently repair it.
DO $$
BEGIN
 IF (SELECT count(*) FROM public.session_blocks WHERE session_id LIKE 'APOLLO-W4-%-R1') <> 18
    OR (SELECT count(*) FROM public.session_block_exercises e JOIN public.session_blocks b ON b.block_id=e.block_id WHERE b.session_id LIKE 'APOLLO-W4-%-R1') <> 37 THEN
   RAISE EXCEPTION 'Apollo Week 4 seed conflict: deterministic content is incomplete or mismatched';
 END IF;
END $$;
